def route(query, context):
    intent = classify_intent(query)          # 意图分类
    complexity = classify_complexity(query)  # 复杂度分类
    if intent == "chitchat":
        return pipeline("friendly_redirect")
    if intent == "operation":
        return pipeline("tool_execute")      # 工具+确认(AG-003)
    if complexity == "complex":
        return pipeline("iterative_rag")     # 分解+迭代(RG-042)
    if intent in ("compare", "summarize"):
        return pipeline("multi_doc")         # 多文档综合(LP-031)
    return pipeline("simple_rag")            # 默认直通
```

